void stage_decide198(unsigned row,unsigned route,unsigned checkpoint,unsigned objectives,unsigned who,unsigned out[4]){const CampaignStageDefinition200*d=row<9?campaignStages200+row:campaignLaterStages197+row-9;Campaign200 c={0};c.cursor=d->cursor;c.route=route;c.checkpoint=checkpoint;c.objectives=objectives;CampaignStageDecision198 r=campaign_stage_decide198(d,&c,(int)who);out[0]=r.write;out[1]=r.objectives;out[2]=r.message;out[3]=r.talk;}
int stage_near198(unsigned row,unsigned cursor,unsigned map,unsigned hp,float x,float y){const CampaignStageDefinition200*d=row<9?campaignStages200+row:campaignLaterStages197+row-9;Campaign200 c={0};c.cursor=cursor;c.route=1;c.lineage=1;NpcState55 state={0};if(!campaign_store200(&state,&c))abort();Combat*g=calloc(1,sizeof(*g));if(!g)abort();g->mapId=map;g->hp=(int)hp;g->x=x;g->y=y;CampaignStage200 stage={g,&state,d,1};int result=campaign_stage_near200(&stage);npc_state_clear55(&state);free(g);return result;}
